/**
 * Order Routes — Order lifecycle management.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const orderController = require('../controllers/order.controller');
const { authenticate, authorize } = require('../middleware/auth.middleware');
const { validate, schemas } = require('../middleware/validator.middleware');

// All order routes require authentication
router.use(authenticate);

// Place a new order
router.post('/', validate(schemas.createOrder), orderController.createOrder);

// Get order by ID (customer sees own, admin sees all)
router.get('/:id', validate(schemas.idParam), orderController.getOrderById);

// Cancel order (within 2-hour window)
router.post('/:id/cancel', validate(schemas.cancelOrder), orderController.cancelOrder);

module.exports = router;
